package net.civeira.phylax.feature.observe.observedissue.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFail;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssue;
import net.civeira.phylax.feature.observe.observedissue.domain.valueobject.UsersVO;

@RequiredArgsConstructor
public class UsersValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<UsersVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<Integer> getUsers() {
    return value.map(UsersVO::getUsers);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<UsersVO> getUsersValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public UsersVO readUsers(final Optional<ObservedIssue> original, final ConstraintFailList fails) {
    UsersVO result = value.orElse(original.map(ObservedIssue::getUsersValue).orElse(null));
    if (null == result) {
      fails.add(new ConstraintFail("REQUIRED", "users", null));
    }
    return result;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetUsers() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetUsersIfMatches(final String field) {
    if ("users".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param users
   * @return
   */
  public T users(UsersVO users) {
    this.value = Optional.of(users);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param users
   * @return
   */
  public T users(Optional<UsersVO> users) {
    this.value = users;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param users
   * @return
   */
  public T users(Integer users) {
    this.value = Optional.of(UsersVO.from(users));
    return this.holder;
  }
}
